  hl_f_take:"Retrait",
  hl_f_lg1:"Lettres de l'ami vers vous",
  hl_f_lg2:"Vos lettres vers l'ami",
  hl_f2_old:"Ancienne boîte",
  hl_f2_new:"Nouvelle boîte",
